const isLpn=(v)=>/^RM\d{12}$/i.test(String(v||'').trim());
const dateDigits=(date)=>String(date||today()).replace(/\D/g,'').slice(0,8).padEnd(8,'0');
function nextLpnForDate(date,records=[],extraItems=[]){const day=dateDigits(date);let max=0;for(const r of records||[])for(const i of r.items||[]){const m=String(i.lpn||'').match(/^RM(\d{8})(\d{4})$/i);if(m&&m[1]===day)max=Math.max(max,Number(m[2])||0);}for(const i of extraItems||[]){const m=String(i.lpn||'').match(/^RM(\d{8})(\d{4})$/i);if(m&&m[1]===day)max=Math.max(max,Number(m[2])||0);}return `RM${day}${String(max+1).padStart(4,'0')}`;}
async function migrateLegacyLpns(){const records=await allReceipts();const used=new Set();const maxByDay=new Map();for(const r of records)for(const i of r.items||[]){const m=String(i.lpn||'').match(/^RM(\d{8})(\d{4})$/i);if(m){used.add(m[0].toUpperCase());maxByDay.set(m[1],Math.max(maxByDay.get(m[1])||0,Number(m[2])||0));}}let changed=0;for(const r of [...records].reverse()){let dirty=false;const day=dateDigits(today());const items=(r.items||[]).map(i=>{const next={...i};if(!isLpn(next.lpn)){if(!next.location&&String(next.lpn||'').trim())next.location=String(next.lpn).trim();let n=(maxByDay.get(day)||0)+1;let candidate=`RM${day}${String(n).padStart(4,'0')}`;while(used.has(candidate)){n++;candidate=`RM${day}${String(n).padStart(4,'0')}`;}next.lpn=candidate;maxByDay.set(day,n);used.add(candidate);dirty=true;}if(next.location===undefined){next.location='';dirty=true;}return next;});if(dirty){await saveReceipt({...r,items,updatedAt:new Date().toISOString()});changed++;}}return changed;}
