async function db(){return openDB(DB_NAME,4,{upgrade(d,oldVersion){if(oldVersion<1){d.createObjectStore('receipts',{keyPath:'id'});d.createObjectStore('settings',{keyPath:'key'});}if(!d.objectStoreNames.contains('fiveS'))d.createObjectStore('fiveS',{keyPath:'id'});if(!d.objectStoreNames.contains('scanSessions'))d.createObjectStore('scanSessions',{keyPath:'id'});}});}
async function allScanSessions(){const d=await db();return (await d.getAll('scanSessions')).sort((a,b)=>(b.startedAt||'').localeCompare(a.startedAt||''));}
async function saveScanSession(session){const d=await db();await d.put('scanSessions',session);return session;}
async function allFiveS(){const d=await db();return (await d.getAll('fiveS')).sort((a,b)=>(b.updatedAt||b.date||'').localeCompare(a.updatedAt||a.date||''));}
async function saveFiveS(record){const d=await db();await d.put('fiveS',record);return record;}
async function deleteFiveS(id){const d=await db();await d.delete('fiveS',id);}
